
-- 写入 2026-07-17 调价后全国准确油价（来源：国家发改委/各省发改委调价公告）
-- p92/p95/p98/p0 均为各省零售限价，pm10/pm20/pm35 为低标号柴油（行业差价 +0.10/+0.20/+0.35）
ON CONFLICT (city) DO UPDATE SET
  p92=EXCLUDED.p92, p95=EXCLUDED.p95, p98=EXCLUDED.p98, p0=EXCLUDED.p0,
  pm10=EXCLUDED.pm10, pm20=EXCLUDED.pm20, pm35=EXCLUDED.pm35,
  update_date=EXCLUDED.update_date, trend=EXCLUDED.trend, trend_date=EXCLUDED.trend_date,
  next_adjust_date=EXCLUDED.next_adjust_date, next_trend=EXCLUDED.next_trend,
  next_trend_text=EXCLUDED.next_trend_text, fetched_at=EXCLUDED.fetched_at, source=EXCLUDED.source;
